<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Чем представление отличается от предписания казначейства?", "acceptedAnswer": {"@type": "Answer", "text": "Представление содержит информацию о нарушениях и требования их устранить; предписание — требования возместить ущерб публично-правовому образованию. Предписание выносится, когда нарушение невозможно устранить либо оно не устранено в срок из представления и при этом сумму ущерба можно определить (ст. 270.2 БК)."}}, {"@type": "Question", "name": "В какой срок исполняется представление казначейства?", "acceptedAnswer": {"@type": "Answer", "text": "В срок, указанный в самом представлении. Если срок в документе не указан, действует правило статьи 270.2 Бюджетного кодекса — 30 календарных дней со дня получения представления. Дату получения фиксируйте документально: от неё считается весь календарь."}}, {"@type": "Question", "name": "Можно ли продлить срок исполнения представления или предписания?", "acceptedAnswer": {"@type": "Answer", "text": "Да, по решению органа контроля срок может быть продлён, но не более одного раза — по обращению объекта контроля. Обращение подавайте заранее, с графиком мероприятий и объективными причинами; порядок продления определяют федеральные стандарты внутреннего государственного финансового контроля."}}, {"@type": "Question", "name": "Что будет, если не исполнить предписание казначейства?", "acceptedAnswer": {"@type": "Answer", "text": "Часть 20 статьи 19.5 КоАП предусматривает штраф на должностных лиц от 20 000 до 50 000 ₽ либо дисквалификацию на срок от одного года до двух лет. За повторное невыполнение действует часть 20.1 той же статьи. Невозмещённый ущерб орган контроля взыскивает в судебном порядке."}}, {"@type": "Question", "name": "Как обжаловать предписание казначейства без суда?", "acceptedAnswer": {"@type": "Answer", "text": "По постановлению Правительства № 1237: подать жалобу в орган контроля в течение 10 рабочих дней со дня получения предписания. Жалобу рассматривает руководитель органа или уполномоченное лицо не более 20 рабочих дней; итог — полное или частичное удовлетворение либо отказ."}}, {"@type": "Question", "name": "Какой срок подачи досудебной жалобы?", "acceptedAnswer": {"@type": "Answer", "text": "На решение органа контроля или действия (бездействие) его должностных лиц — 30 календарных дней со дня, когда заявитель узнал о нарушении своих прав. На предписание срок короче — 10 рабочих дней со дня его получения. Пропуск срока — основание оставить жалобу без рассмотрения."}}, {"@type": "Question", "name": "Приостанавливает ли жалоба исполнение представления или предписания?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Пункт 7 стандарта № 1237 прямо устанавливает, что подача жалобы не приостанавливает исполнение обжалуемого решения. Срок исполнения продолжает течь, поэтому параллельно с жалобой просите продление срока, а в суде — приостановление действия акта по ч. 3 ст. 199 АПК."}}, {"@type": "Question", "name": "Как подать жалобу юридическому лицу?", "acceptedAnswer": {"@type": "Answer", "text": "В электронном виде — на адрес электронной почты органа контроля (публикуется на его официальном сайте), с усиленной квалифицированной электронной подписью. Либо на бумажном носителе — лично или почтовым отправлением. До принятия решения жалобу можно отозвать, но повторная подача по тем же основаниям не допускается."}}, {"@type": "Question", "name": "Когда жалобу оставят без рассмотрения?", "acceptedAnswer": {"@type": "Answer", "text": "Пункт 11 стандарта № 1237 называет основания: пропуск срока подачи, отсутствие подписи или подтверждения полномочий, отсутствие наименования либо адреса заявителя, нечитаемый текст, отзыв жалобы, уже принятое решение по тем же основаниям, судебный спор по тому же предмету, несоответствие предмета жалобы предмету решения. Возврат — в течение 5 рабочих дней."}}, {"@type": "Question", "name": "Обязательно ли подавать досудебную жалобу перед судом?", "acceptedAnswer": {"@type": "Answer", "text": "Стандарт № 1237 обязательности досудебного порядка не устанавливает — жалоба сформулирована как право объекта контроля. Можно обратиться сразу в арбитражный суд по главе 24 АПК. Но учитывайте: пока идёт судебное разбирательство по тому же предмету, досудебную жалобу оставят без рассмотрения."}}, {"@type": "Question", "name": "В какой срок можно оспорить предписание в суде?", "acceptedAnswer": {"@type": "Answer", "text": "Три месяца со дня, когда организации стало известно о нарушении её прав и законных интересов (ч. 4 ст. 198 АПК). Представления и предписания оспариваются как ненормативные правовые акты по правилам главы 24 АПК; пропущенный по уважительной причине срок суд может восстановить."}}, {"@type": "Question", "name": "Можно ли остановить исполнение предписания на время судебного спора?", "acceptedAnswer": {"@type": "Answer", "text": "Да, через суд: по ходатайству заявителя арбитражный суд вправе приостановить действие оспариваемого акта (ч. 3 ст. 199 АПК). Ходатайство мотивируйте последствиями немедленного исполнения — изъятием оборотных средств, риском срыва государственных контрактов. Досудебная жалоба такого эффекта не даёт."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Как обжаловать предписание казначейства", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Зафиксировать сроки", "text": "Определить дату получения предписания и рассчитать два срока: исполнения (указан в документе) и досудебного обжалования — 10 рабочих дней со дня получения по пункту 5 постановления № 1237."}, {"@type": "HowToStep", "position": 2, "name": "Разобрать требования по эпизодам", "text": "Сопоставить каждый вменённый эпизод с нормами, условиями контракта и платёжными документами; решить, что исполняется, а что обжалуется, — исполнение бесспорной части усиливает позицию по спорной."}, {"@type": "HowToStep", "position": 3, "name": "Подготовить жалобу", "text": "Указать наименование и адрес заявителя, реквизиты предписания, доводы по каждому эпизоду со ссылками на нормы и документы; подписать руководителем или представителем с доверенностью."}, {"@type": "HowToStep", "position": 4, "name": "Подать в орган контроля", "text": "Направить жалобу на адрес электронной почты органа контроля (с сайта органа) с усиленной квалифицированной электронной подписью либо на бумаге лично или почтой; помнить — повторная жалоба по тем же основаниям не допускается."}, {"@type": "HowToStep", "position": 5, "name": "Работать параллельно с исполнением", "text": "Жалоба не приостанавливает предписание (п. 7 стандарта № 1237): до решения по ней просить продление срока исполнения (возможно один раз) и готовить возмещение на случай отказа."}, {"@type": "HowToStep", "position": 6, "name": "При отказе — идти в суд", "text": "Оспорить предписание в арбитражном суде по главе 24 АПК в течение 3 месяцев (ч. 4 ст. 198) и заявить ходатайство о приостановлении действия акта по ч. 3 ст. 199 АПК."}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "DefinedTermSet", "name": "Термины: представление и предписание органа финансового контроля", "inLanguage": "ru-RU", "hasDefinedTerm": [{"@type": "DefinedTerm", "name": "Представление", "description": "Документ органа внутреннего государственного финансового контроля с информацией о нарушениях и требованиями об их устранении; исполняется в указанный в нём срок или в течение 30 календарных дней со дня получения (ст. 270.2 БК)."}, {"@type": "DefinedTerm", "name": "Предписание", "description": "Документ того же органа с обязательными требованиями о возмещении ущерба публично-правовому образованию; направляется при невозможности устранения либо неустранении нарушения в срок из представления, когда сумму ущерба можно определить."}, {"@type": "DefinedTerm", "name": "Орган внутреннего государственного финансового контроля", "description": "Федеральное казначейство и его территориальные органы, осуществляющие контроль в финансово-бюджетной сфере по статье 269.2 Бюджетного кодекса."}, {"@type": "DefinedTerm", "name": "Стандарт № 1237", "description": "Постановление Правительства РФ от 17.08.2020 № 1237 — федеральный стандарт досудебного обжалования решений и действий (бездействия) органов внутреннего государственного (муниципального) финансового контроля."}, {"@type": "DefinedTerm", "name": "Стандарт № 1095", "description": "Постановление Правительства РФ от 23.07.2020 № 1095 — федеральный стандарт реализации результатов проверок, ревизий и обследований: порядок вынесения представлений и предписаний по итогам контрольных мероприятий."}, {"@type": "DefinedTerm", "name": "Досудебная жалоба", "description": "Обращение объекта контроля к руководителю органа контроля об отмене или изменении решения; на предписание подаётся за 10 рабочих дней, исполнение обжалуемого решения не приостанавливает."}, {"@type": "DefinedTerm", "name": "Дисквалификация", "description": "Административное наказание — лишение должностного лица права занимать руководящие должности; за невыполнение предписания органа финансового контроля назначается на срок от 1 года до 2 лет (ч. 20 ст. 19.5 КоАП)."}, {"@type": "DefinedTerm", "name": "Приостановление действия акта", "description": "Обеспечительная мера арбитражного суда по ч. 3 ст. 199 АПК: по ходатайству заявителя суд приостанавливает действие оспариваемого предписания или представления до разрешения спора."}]}
</script>
